// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address actor, uint256 amount, bytes memory data) public {
        vm.assume(actor != c.owner());
        vm.assume(address(c).balance == 0);
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.sendMoney(actor, amount, data) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
